"""Write an exported anticipation prior (anticipation-bound.py --export) into src/sim/anticipation-prior.ts.
usage: python3 -I scripts/diag/write-anticipation-prior.py prior.json "source label" """
import sys, json
d = json.load(open(sys.argv[1])); label = sys.argv[2]
body = json.dumps(d["cells"], separators=(",", ":"))
open("src/sim/anticipation-prior.ts", "w").write(
    "/** Football experience for GAZE anticipation (generated by scripts/diag/write-anticipation-prior.py; do not edit).\n"
    f" * Source: {label}. Key: {d['key']}. Frame: {d['frame']}. */\n"
    f"export const PRIOR_SOURCE = {json.dumps(label)};\n"
    "/** key -> horizon (s, as string) -> [along travel, across toward own sideline, n]. */\n"
    f"export const ANTICIPATION_PRIOR: Record<string, Record<string, [number, number, number]>> = {body};\n")
print("wrote", len(d["cells"]), "keys")
